const formula = new MathTex({ latex: 'f(x)=\\frac{x^2}{2},\\quad a=1,\\qquad m_h=\\frac{f(1+h)-f(1)}{h}=1+\\frac{h}{2}\\longrightarrow f\'(1)=1' });
await formula.waitForRender();
formula.scale(0.65);
